public boolean unlink(ListNodeImpl<E> node) {
	if (node == null) {
		return false;
	}

	ListNodeImpl<E> current = head;
	ListNodeImpl<E> previous = null;
	while (current != null) {
		if (current == node) {
			if (previous == null) {
				head = head.next;
			} else {
				previous.next = current.next;
			}
			return true;
		}
		previous = current;
		current = current.next;
	}
	return false;
}

