    // Initialize the token as an empty string
    String token = "";

    // Loop until a terminator is encountered
    while (!Character.isWhitespace(terminators[0])) {
        // If the current character is not a terminator, add it to the token
        if (!Character.isWhitespace(terminators[0]) && !Character.isWhitespace(terminators[0])) {
            token += terminators[0];
        }
        // Move to the next character
        terminators[0]++;
    }

    // Return the token
    return token;
}

